\n// path: test/fitur/dompet/page/form_dompet_test.dart\nimport 'package:flutter/material.dart';\nimport 'package:flutter_riverpod/flutter_riverpod.dart';\nimport 'package:flutter_test/flutter_test.dart';\nimport 'package:mockito/annotations.dart';\nimport 'package:mockito/mockito.dart';\nimport 'package:wifi/fitur/database/provider/operasi_sqlite_provider.dart';\nimport 'package:wifi/fitur/dompet/model/dompet_model.dart';\nimport 'package:wifi/fitur/dompet/page/form_dompet.dart';\nimport 'package:wifi/fitur/sinkronisasi/layanan_cek_sinkronisasi.dart';\nimport 'package:wifi/shared/services/koneksi_internet_service.dart';\n\nimport 'form_dompet_test.mocks.dart';\n\n@GenerateMocks([DompetOpSqlite, KoneksiInternetService, LayananCekSinkronisasi])\nvoid main() {\n  group('FormDompet', () {\n    late ProviderContainer container;\n    late MockDompetOpSqlite mockDompetOpSqlite;\n    late MockKoneksiInternetService mockKoneksiInternetService;\n    late MockLayananCekSinkronisasi mockLayananCekSinkronisasi;\n\n    setUp(() {\n      mockDompetOpSqlite = MockDompetOpSqlite();\n      mockKoneksiInternetService = MockKoneksiInternetService();\n      mockLayananCekSinkronisasi = MockLayananCekSinkronisasi();\n      container = ProviderContainer(\n        overrides: [\n          dompetOpSqliteProvider.overrideWithValue(mockDompetOpSqlite),\n          koneksiInternetServiceProvider.overrideWithValue(mockKoneksiInternetService),\n          layananCekSinkronisasiProvider.overrideWithValue(mockLayananCekSinkronisasi),\n        ],\n      );\n    });\n\n    tearDown(() {\n      container.dispose();\n    });\n\n    final dompet = DompetModel(\n      id: '1',\n      nama: 'Dompet Lama',\n      saldo: 100000,\n      dibuatPada: DateTime.now(),\n      diperbaruiPada: DateTime.now(),\n    );\n\n    Future<void> pumpForm(WidgetTester tester, {DompetModel? dompet}) async {\n      await tester.pumpWidget(\n        UncontrolledProviderScope(\n          container: container,\n          child: MaterialApp(\n            home: FormDompet(dompet: dompet),\n          ),\n        ),\n      );\n    }\n\n    testWidgets('01. Tampilan awal untuk mode tambah', (tester) async {\n      await pumpForm(tester);\n\n      expect(find.text('Tambah Dompet Baru'), findsOneWidget);\n      expect(find.widgetWithText(TextFormField, ''), findsOneWidget);\n      expect(find.widgetWithText(ElevatedButton, 'Simpan'), findsOneWidget);\n    });\n\n    testWidgets('02. Tampilan awal untuk mode edit', (tester) async {\n      await pumpForm(tester, dompet: dompet);\n\n      expect(find.text('Edit Nama Dompet'), findsOneWidget);\n      expect(find.widgetWithText(TextFormField, 'Dompet Lama'), findsOneWidget);\n    });\n\n    testWidgets('03. Validasi form tidak boleh kosong', (tester) async {\n      await pumpForm(tester);\n\n      await tester.tap(find.widgetWithText(ElevatedButton, 'Simpan'));\n      await tester.pump();\n\n      expect(find.text('Nama dompet tidak boleh kosong'), findsOneWidget);\n    });\n\n    testWidgets('04. Simpan form untuk tambah dompet berhasil', (tester) async {\n      when(mockDompetOpSqlite.tambahDompet(any)).thenAnswer((_) async {});\n      when(mockKoneksiInternetService.cekKoneksiLokal()).thenAnswer((_) async => true);\n      when(mockLayananCekSinkronisasi.jalankanCekSinkronisasi()).thenReturn(null);\n      await pumpForm(tester);\n\n      await tester.enterText(find.byType(TextFormField), 'Dompet Baru');\n      await tester.tap(find.widgetWithText(ElevatedButton, 'Simpan'));\n      await tester.pump();\n      verify(mockDompetOpSqlite.tambahDompet(any)).called(1);\n    });\n\n    testWidgets('05. Simpan form untuk edit dompet berhasil', (tester) async {\n      when(mockDompetOpSqlite.updateDompet(any)).thenAnswer((_) async {});\n      when(mockKoneksiInternetService.cekKoneksiLokal()).thenAnswer((_) async => true);\n      when(mockLayananCekSinkronisasi.jalankanCekSinkronisasi()).thenReturn(null);\n\n      await pumpForm(tester, dompet: dompet);\n\n      await tester.enterText(find.byType(TextFormField), 'Dompet Baru');\n      await tester.tap(find.widgetWithText(ElevatedButton, 'Simpan'));\n      await tester.pump();\n\n      verify(mockDompetOpSqlite.updateDompet(any)).called(1);\n    });\n\n  });\n}\n